//This is the FV env to verify the golden fifo generated by claude.


module fv_afifo_full #(
  parameter int DW = 8,
  parameter int AW = 4, // depth = 2^AW (AW=4 -> 4)
  parameter int SEQW = 5,
  parameter int DEPTH = (1<<AW)
)(
  input logic          w_clk, wrst_n, w_en, full,
  input logic [DW-1:0] data_in,
  input logic [AW-1:0] w_ptr,              // binary write index
  input logic [AW:0]   wbin,               // full write bin (AW+1, wrap bit)
  input logic [AW:0]   wgray,              // write gray
  input logic          r_clk, rrst_n, r_en, empty,
  input logic [DW-1:0] data_out,
  input logic [AW-1:0] r_ptr,              // binary read index
  input logic [AW:0]   rbin,               // full read bin
  input logic [AW:0]   rgray               // read gray
);


   logic 	       wr_fire, rd_fire;
   assign wr_fire = w_en && !full;
   assign rd_fire = r_en && !empty;
   

//==========================================================
// --reset--
//==========================================================

      //check empty after reset
      chk_fv_empty_after_reset:
	assert property (@(posedge r_clk) 
		      $rose(rrst_n) |-> empty);

      //check no full after reset
      chk_fv_no_full_after_reset:
	assert property (@(posedge w_clk)
		      $rose(wrst_n) |-> !full);

      //stable data_out when there is no read
      chk_fv_stable_dout:
	assert property (@(posedge r_clk) disable iff (!rrst_n)
			 !rd_fire |=> $stable(data_out));


endmodule
